const blizzardSpiritSheet=new Image();blizzardSpiritSheet.assetSrc='assets/blizzard-spirit-v1.png';
function beginBlizzardSpirit(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'blizzardTurningShelter',bespoke:true,windup:1,angle:Math.atan2(p.y-e.y,p.x-e.x),origin:{x:e.x,y:e.y},waves:0};}
function blizzardSpiritDanger(a,index,point){let d=dist(a.origin,point),delta=Math.atan2(point.y-a.origin.y,point.x-a.origin.x)-a.angle-index*Math.PI/3;delta=Math.atan2(Math.sin(delta),Math.cos(delta));return d>45+1e-8&&d<=300+1e-8&&Math.abs(delta)>Math.PI/4+1e-8;}
const blizzardSpiritAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r5e7')return blizzardSpiritAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='blizzardTurningShelter'){
  e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=320&&clear){beginBlizzardSpirit(e);return;}e.state='idle';if(d>800&&!e.aware||d<=220)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,68*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;
 }
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;while(a.waves<3&&e.elapsed>=Math.round((1+a.waves*.8)*1e6)/1e6){let index=a.waves++;e.struck=true;if(blizzardSpiritDanger(a,index,p)&&lineClear(a.origin,p))hurt(38);playSound('frost',e.x,e.y);}
 if(e.elapsed>=3.3){e.attack=null;e.state='idle';e.t=3;}
};
const blizzardSpiritDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r5e7'||!blizzardSpiritSheet.complete||!blizzardSpiritSheet.naturalWidth||!blizzardSpiritSheet.naturalHeight)return blizzardSpiritDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='blizzardTurningShelter')f={row:2,col:e.elapsed<.5?0:e.elapsed<1?1:e.elapsed<2.8?2:3};let q=project(e.x,e.y),sw=blizzardSpiritSheet.naturalWidth/4,sh=blizzardSpiritSheet.naturalHeight/3,w=220,h=w*sh/sw,bob=e.hp>0?Math.sin((e.anim||0)*3)*3:0;ctx.save();ctx.translate(q.x,q.y-bob);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,blizzardSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.85,w,h);else ctx.drawImage(blizzardSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*.85,w,h);ctx.restore();return true;};
const blizzardSpiritSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r5e7'?135:blizzardSpiritSizeBase(e);
function paintBlizzardSpirit(a,index,fired){let angle=a.angle+index*Math.PI/3,start=angle+Math.PI/4,end=angle+Math.PI*7/4,q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=fired?'#baeaff55':'#5c9fb31c';ctx.strokeStyle=fired?'#d9f6ff':'#8bc5e8';ctx.lineWidth=fired?3:1;ctx.beginPath();ctx.arc(0,0,300,start,end);ctx.lineTo(Math.cos(end)*45,Math.sin(end)*45);ctx.arc(0,0,45,end,start,true);ctx.closePath();ctx.fill();ctx.stroke();if(!fired){ctx.strokeStyle='#b4f0c7';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(Math.cos(angle-Math.PI/4)*45,Math.sin(angle-Math.PI/4)*45);ctx.lineTo(Math.cos(angle-Math.PI/4)*300,Math.sin(angle-Math.PI/4)*300);ctx.arc(0,0,300,angle-Math.PI/4,angle+Math.PI/4);ctx.lineTo(Math.cos(angle+Math.PI/4)*45,Math.sin(angle+Math.PI/4)*45);ctx.stroke();}ctx.restore();}
const blizzardSpiritGroundBase=drawGroundEffects;drawGroundEffects=()=>{blizzardSpiritGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r5e7'):enemies)){let a=e.attack;if(e.species!=='r5e7'||e.hp<=0||a?.pattern!=='blizzardTurningShelter'||!visibleAt(e.x,e.y))continue;if(a.waves<3)paintBlizzardSpirit(a,a.waves,false);if(a.waves>0&&e.elapsed<1+(a.waves-1)*.8+.16)paintBlizzardSpirit(a,a.waves-1,true);groundRing(a.origin.x,a.origin.y,45,'#b4f0c7',1);}};
